// No identity storage, cookies, fingerprinting or IP collection.
export class VisibleClock {
 constructor(now=()=>performance.now()){this.now=now;this.total=0;this.last=now();this.lastActivity=this.last;this.active=false;}
 sample(){const n=this.now();if(this.active)this.total+=Math.max(0,Math.min(n,this.lastActivity+60000)-this.last);this.last=n;return Math.floor(this.total);}
 setActive(active){this.sample();this.active=active;}
 activity(){this.sample();this.lastActivity=this.now();}
}
const messages={disabledPreview:'Public preview: engagement is not recorded.',unavailable:'Tracking inactive: storage or API unavailable; activity is not recorded.',awaitingConsent:'Tracking inactive until you choose Continue.',declined:'Tracking inactive: consent not provided.',recording:'Visible viewing activity is being recorded. Identity is self-reported.',notRecorded:'Tracking inactive: latest activity was not recorded. Retrying queued activity.',recorded:'Visible viewing activity saved. Identity is self-reported.',closed:'Viewing ended; no further time is counted.',untracked:'Untracked public link: copying does not record delivery or forwarding.'};
function consent(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.id='tcas-engagement-consent';dialog.setAttribute('aria-labelledby','tcas-consent-title');dialog.innerHTML=`<style>#tcas-engagement-consent{max-width:440px;width:calc(100% - 56px);padding:28px;border:1px solid #c5d3db;border-radius:16px;background:#fff;color:#231f20;font:16px/1.5 system-ui;box-shadow:0 20px 80px #0005}#tcas-engagement-consent::backdrop{background:#102b3f66}#tcas-engagement-consent label{display:block;margin:16px 0}#tcas-engagement-consent input{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #849ba9;border-radius:6px;font:inherit}#tcas-engagement-consent button{padding:12px 18px;border-radius:7px;border:1px solid #eb2127;background:#eb2127;color:white;font:inherit;margin:8px 8px 0 0}#tcas-engagement-consent button[value=cancel]{background:white;color:#eb2127}</style><form><h2 id="tcas-consent-title">View this proposal</h2><p>TCAS records the details you provide and visible viewing activity for this proposal. Identity is not verified.</p><p>Records are available to the proposal owner for up to 30 days. This does not verify attention or detect off-app forwarding.</p><label>Your name<input name="name" autocomplete="name" maxlength="120" required></label><label>Your email<input name="email" type="email" autocomplete="email" maxlength="254" required></label><button type="submit">Continue</button><button type="button" value="cancel">Preview without recording</button></form>`;document.body.append(dialog);let done=false;const finish=data=>{if(done)return;done=true;dialog.close();dialog.remove();resolve(data);};dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();finish({declaredName:dialog.querySelector('[name=name]').value,declaredEmail:dialog.querySelector('[name=email]').value,consent:true});});dialog.querySelector('[value=cancel]').onclick=()=>finish(null);dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null);});dialog.showModal();});}
function publicPreviewURL(){const u=new URL(location.href);u.searchParams.delete('p');u.hash='';return u.href;}
export async function initializeEngagement({apiBase='',proposalId='factory-line-v3',onStatus=()=>{},getStage=()=>null}={}){
 const url=new URL(location.href),token=url.searchParams.get('p')??url.pathname.match(/^\/p\/([a-f0-9]{32})\/?$/)?.[1];
 const tracker={enabled:false,status:'disabledPreview',stage:()=>{},complete:()=>{},close:()=>{},share:async()=>{set('untracked');return {shareURL:publicPreviewURL(),tracked:false,copied:false};}};
 function set(code){tracker.status=code;try{onStatus({code,message:messages[code]??code,enabled:tracker.enabled});}catch{}}
 const endpoint=action=>`${apiBase.replace(/\/$/,'')}/api/engagement?action=${action}`;
 async function request(action,body){const r=await fetch(endpoint(action),{method:body?'POST':'GET',credentials:'omit',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error??'Engagement unavailable'),{status:r.status});return data;}
 if(!token){set('disabledPreview');return tracker;}if(!/^[a-f0-9]{32}$/.test(token)){set('unavailable');return tracker;}
 try{const h=await request('health');if(h.status!=='ready')throw Error();}catch{set('unavailable');return tracker;}
 set('awaitingConsent');const identity=await consent();if(!identity){set('declined');return tracker;}
 let started;try{started=await request('start',{token,proposalId,...identity});}catch{set('unavailable');return tracker;}
 const session=started.session,clock=new VisibleClock();let seq=0,closed=false,busy=false,queue=[],timer;const listeners=[];
 const listen=(target,type,fn,opts)=>{target.addEventListener(type,fn,opts);listeners.push(()=>target.removeEventListener(type,fn,opts));};
 const focused=()=>document.visibilityState==='visible'&&document.hasFocus();clock.setActive(focused());
 tracker.enabled=true;set('recording');
 async function drain(){if(busy||!queue.length)return;busy=true;try{while(queue.length){await request('event',queue[0]);queue.shift();set(closed?'closed':'recorded');}}catch(e){set('notRecorded');if([400,401,409,410].includes(e.status)){tracker.enabled=false;closed=true;clearInterval(timer);clock.setActive(false);listeners.forEach(f=>f());}}finally{busy=false;}}
 function enqueue(type,stage=null){if(closed||!tracker.enabled)return;const payload={session,seq:++seq,type,visibleMs:Math.min(clock.sample(),43200000),...(stage?{stage}:{})};if(queue.length>=120){tracker.enabled=false;set('notRecorded');clock.setActive(false);clearInterval(timer);return;}queue.push(payload);void drain();return payload;}
 const activity=()=>clock.activity();for(const e of ['pointerdown','pointermove','keydown','touchstart','wheel'])listen(document,e,activity,{passive:true});
 function visibility(){// Account for the preceding interval before changing active state.
 clock.sample();enqueue('heartbeat');clock.setActive(focused());}
 listen(document,'visibilitychange',visibility);listen(window,'focus',visibility);listen(window,'blur',visibility);
 tracker.stage=id=>{if(typeof id==='string')enqueue('stage',id);};tracker.complete=()=>enqueue('complete',getStage());
 tracker.share=async({intendedName='',intendedEmail=''}={})=>{if(closed||!tracker.enabled){set('untracked');return {shareURL:publicPreviewURL(),tracked:false,copied:false};}try{const child=await request('forward',{session,intendedName,intendedEmail});let copied=false;try{await navigator.clipboard.writeText(child.shareURL);copied=true;}catch{}return {...child,tracked:true,copied,note:'Share link created. This does not mean email delivery or forwarding.'};}catch{set('notRecorded');return {tracked:false,copied:false,error:'Share link was not created.'};}};
 tracker.close=()=>{if(closed)return;enqueue('close');closed=true;clock.setActive(false);clearInterval(timer);listeners.forEach(f=>f());for(const payload of queue){try{// A queued beacon is not an acknowledgement of persistence.
 navigator.sendBeacon?.(endpoint('event'),new Blob([JSON.stringify(payload)],{type:'application/json'}));}catch{}}set(queue.length?'notRecorded':'closed');};
 listen(window,'pagehide',()=>tracker.close());timer=setInterval(()=>{if(!closed){enqueue('heartbeat');void drain();}},10000);return tracker;
}
